#include "ui/SandboxWorkspaceSystem.h"
namespace subspace {
std::string SandboxWorkspaceSystem::Title() const {switch(mode_){case SandboxWorkspaceMode::Flight:return"FLIGHT";case SandboxWorkspaceMode::GalaxyMap:return"GALAXY MAP";case SandboxWorkspaceMode::SystemMap:return"SYSTEM MAP";case SandboxWorkspaceMode::PlanetSurvey:return"PLANETARY SURVEY";case SandboxWorkspaceMode::PlanetaryManufacturing:return"PLANETARY MANUFACTURING";case SandboxWorkspaceMode::StationBuilder:return"STATION BUILDER";case SandboxWorkspaceMode::ShipBuilder:return"SHIP BUILDER";case SandboxWorkspaceMode::HangarFitting:return"HANGAR & FITTING";case SandboxWorkspaceMode::MarketContracts:return"MARKET & CONTRACTS";case SandboxWorkspaceMode::Exploration:return"EXPLORATION";case SandboxWorkspaceMode::FleetCorporation:return"FLEET & CORPORATION";}return"FLIGHT";}
std::vector<std::string> SandboxWorkspaceSystem::Actions() const {switch(mode_){case SandboxWorkspaceMode::GalaxyMap:return{"Inspect generated systems","Cycle strategic overlay","Plot fastest / safest / fuel route","Enter selected solar system","Back to flight"};case SandboxWorkspaceMode::SystemMap:return{"Select destination","Bookmark / intelligence","Vector travel","Inspect orbital/belt/ring region","Review hazards / travel cost"};case SandboxWorkspaceMode::PlanetSurvey:return{"Preliminary scan","Detailed survey","Evaluate industry","Select tether site"};case SandboxWorkspaceMode::PlanetaryManufacturing:return{"Place extraction","Place processing","Route logistics","Review throughput / bottlenecks","Export through Space Elevator"};case SandboxWorkspaceMode::StationBuilder:return{"Place core","Add connected modules","Validate power / services","Review material bill","Commit construction"};case SandboxWorkspaceMode::ShipBuilder:return{"Pick certified kitbash category","LMB drag part to compatible socket","Mirror / symmetry","Review material bill","Validate / queue blueprint"};case SandboxWorkspaceMode::HangarFitting:return{"Fit physical modules","Ammo / drones / cargo","Damage / repair","Power / heat / sensors","Undock"};case SandboxWorkspaceMode::MarketContracts:return{"Buy/sell orders","Causal price history","Shortages / contracts","Faction demand","Reputation"};case SandboxWorkspaceMode::Exploration:return{"Directional scan","Launch probes","Resolve signature","Publish intelligence / bookmark","Inspect Subspace tears"};case SandboxWorkspaceMode::FleetCorporation:return{"Create wing / doctrine","Assign captain / crew","Issue standing order","Manage corporation assets","Sector crises / recovery"};default:return{};}}
} // namespace subspace
